// LiamPlay - sprites de los juegos, recortados de las dos hojas de sprites de LIAM.
// Van como PNG en base64 (data URI) para que el sitio siga siendo solo archivos de texto.
// Uso: if (SPRITES.listo('manzana')) ctx.drawImage(SPRITES.manzana, x, y, ancho, alto);
(function () {
  var D = {
    cabeza: 'data:image/png;base64,',
    manzana: 'data:image/png;base64,',
    p1: 'data:image/png;base64,',
    p2: 'data:image/png;base64,',
    pajaro1: 'data:image/png;base64,',
    pajaro2: 'data:image/png;base64,',
    pajaro3: 'data:image/png;base64,',
    soldado: 'data:image/png;base64,',
    agachado: 'data:image/png;base64,',
    // --- ronda 2: hoja con fondo verde (robots, invasores, dino, asteroides, topos, coches, ladrillos, caras, mina, bandera, fichas) ---
    robot: 'data:image/png;base64,',
    robot_jefe: 'data:image/png;base64,',
    bala: 'data:image/png;base64,',
    exp1: 'data:image/png;base64,',
    exp2: 'data:image/png;base64,',
    exp3: 'data:image/png;base64,',
    inv_nave: 'data:image/png;base64,',
    alien1: 'data:image/png;base64,',
    alien2: 'data:image/png;base64,',
    alien3: 'data:image/png;base64,',
    alien4: 'data:image/png;base64,',
    laser_chico: 'data:image/png;base64,',
    laser: 'data:image/png;base64,',
    dino1: 'data:image/png;base64,',
    dino2: 'data:image/png;base64,',
    dino3: 'data:image/png;base64,',
    cactus_chico: 'data:image/png;base64,',
    cactus: 'data:image/png;base64,',
    ast_nave: 'data:image/png;base64,',
    roca_g: 'data:image/png;base64,',
    roca_m: 'data:image/png;base64,',
    roca_c: 'data:image/png;base64,',
    topo: 'data:image/png;base64,',
    topo_golpe: 'data:image/png;base64,',
    hoyo: 'data:image/png;base64,',
    mazo: 'data:image/png;base64,',
    coche_jugador: 'data:image/png;base64,',
    coche_rojo: 'data:image/png;base64,',
    coche_azul: 'data:image/png;base64,',
    coche_verde: 'data:image/png;base64,',
    coche_amarillo: 'data:image/png;base64,',
    paleta: 'data:image/png;base64,',
    pelota: 'data:image/png;base64,',
    ladrillo_rojo: 'data:image/png;base64,',
    ladrillo_azul: 'data:image/png;base64,',
    ladrillo_verde: 'data:image/png;base64,',
    ladrillo_amarillo: 'data:image/png;base64,',
    ladrillo_morado: 'data:image/png;base64,',
    cara_perro: 'data:image/png;base64,',
    cara_gato: 'data:image/png;base64,',
    cara_conejo: 'data:image/png;base64,',
    cara_zorro: 'data:image/png;base64,',
    cara_rana: 'data:image/png;base64,',
    cara_panda: 'data:image/png;base64,',
    cara_leon: 'data:image/png;base64,',
    cara_buho: 'data:image/png;base64,',
    mina: 'data:image/png;base64,',
    bandera: 'data:image/png;base64,',
    ficha_roja: 'data:image/png;base64,',
    ficha_amarilla: 'data:image/png;base64,',
    ladrillo_naranja: 'data:image/png;base64,',
    ladrillo_rojo4: 'data:image/png;base64,',
  };
  var S = { listo: function (n) { var i = S[n]; return !!(i && i.complete && i.naturalWidth > 0); } };
  // alCargar(fn): avisa una vez cuando ya cargaron todas las imágenes (para los juegos que solo redibujan al tocar).
  var faltan = Object.keys(D).length, avisos = [];
  function una() { if (--faltan === 0) { avisos.forEach(function (f) { try { f(); } catch (e) {} }); avisos = []; } }
  S.alCargar = function (f) { if (faltan <= 0) setTimeout(f, 0); else avisos.push(f); };
  Object.keys(D).forEach(function (k) { var i = new Image(); i.onload = i.onerror = una; i.src = D[k]; S[k] = i; });
  // Dibuja un sprite centrado en (x, y), girado 'ang' radianes.
  // voltea = espejo vertical (útil al girar hacia la izquierda); espejo = espejo horizontal (mirar a la izquierda sin girar).
  S.dibuja = function (n, x, y, w, h, ang, voltea, espejo) {
    if (!S.listo(n)) return false;
    ctx.save(); ctx.imageSmoothingEnabled = false; ctx.translate(x, y);
    if (ang) ctx.rotate(ang);
    if (voltea || espejo) ctx.scale(espejo ? -1 : 1, voltea ? -1 : 1);
    ctx.drawImage(S[n], -w / 2, -h / 2, w, h); ctx.restore(); return true;
  };
  // Dibuja un sprite centrado en (x, y) lo más grande que quepa en maxW x maxH sin deformarlo.
  S.cabe = function (n, x, y, maxW, maxH, ang) {
    if (!S.listo(n)) return false;
    var iw = S[n].naturalWidth || 1, ih = S[n].naturalHeight || iw, k = Math.min(maxW / iw, maxH / ih);
    return S.dibuja(n, x, y, iw * k, ih * k, ang);
  };
  window.SPRITES = S;
})();
